CREATE OR REPLACE FUNCTION $schema.enforce_chat_attachments_bound_at_write_once()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF OLD.bound_at IS NOT NULL AND NEW.bound_at IS DISTINCT FROM OLD.bound_at THEN
        RAISE EXCEPTION 'chat_attachments.bound_at is write-once';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION $schema.gobby_maintenance_epoch_login_guard()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
        DECLARE
            active_epoch UUID;
            supplied_epoch TEXT;
        BEGIN
            IF pg_catalog.pg_is_in_recovery() THEN
                RETURN;
            END IF;

            BEGIN
                SELECT id
                INTO active_epoch
                FROM $schema.maintenance_epochs
                WHERE released_at IS NULL;
            EXCEPTION
                WHEN undefined_table OR invalid_schema_name THEN
                    RETURN;
            END;

            IF active_epoch IS NULL THEN
                RETURN;
            END IF;

            supplied_epoch :=
                pg_catalog.current_setting('gobby.maintenance_epoch', TRUE);
            IF supplied_epoch IS DISTINCT FROM active_epoch::TEXT THEN
                RAISE EXCEPTION USING
                    ERRCODE = '55000',
                    MESSAGE =
                        'Gobby hub maintenance is active; use '
                        '`gobby hub-maintenance status` to inspect it or '
                        '`gobby hub-maintenance resume` from the operator shell.';
            END IF;
        END;
        $function$

CREATE OR REPLACE FUNCTION $schema.refresh_task_state_bucket_from_stage()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'DELETE' THEN
        PERFORM refresh_task_state_bucket(OLD.task_id);
        RETURN OLD;
    END IF;

    PERFORM refresh_task_state_bucket(NEW.task_id);
    IF TG_OP = 'UPDATE' AND OLD.task_id IS DISTINCT FROM NEW.task_id THEN
        PERFORM refresh_task_state_bucket(OLD.task_id);
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION $schema.refresh_task_state_bucket_from_task()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    PERFORM refresh_task_state_bucket(NEW.id);
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION $schema.touch_chat_attachments_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.updated_at IS NOT DISTINCT FROM OLD.updated_at THEN
        NEW.updated_at := NOW();
    END IF;
    RETURN NEW;
END;
$function$
